 session.pendingPackFonts={bundle("b",0,255,0)};runtime.tick(session,&font,&textures);assert(!JavaPackItemModels::has("test:flat"));session.pendingPackFonts={bundle("a",255,0,0)};runtime.tick(session,&font,&textures);assert(JavaPackItemModels::has("test:flat"));auto green=render("test:flat");assert((color(green,48,48)==std::array<unsigned char,3>{{0,255,0}}));assert(green==render("test:flat",true));
