 auto upload=[&](const std::string& key,unsigned char r,unsigned char g,unsigned char b,unsigned char a){TextureData image;image.w=image.h=2;image.numBytes=16;image.transparent=true;image.data=new unsigned char[16];for(int i=0;i<4;++i){image.data[i*4]=r;image.data[i*4+1]=g;image.data[i*4+2]=b;image.data[i*4+3]=a;}auto id=textures.assignTexture(key,image);textures.bind(id);glTexParameteri2(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri2(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);return id;};
